package zw.ac.msu.dzimbahub.auth;
import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.InjectMocks; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.http.ResponseEntity; import org.springframework.security.crypto.password.PasswordEncoder; import zw.ac.msu.dzimbahub.security.JwtService; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class AuthControllerTest {
 @Mock AppUserRepository users; @Mock PasswordEncoder encoder; @Mock JwtService jwt; @InjectMocks AuthController controller;
 @Test void signupCreatesPendingAccountAndDoesNotIssueToken(){when(users.existsByEmailIgnoreCase("tenant@example.com")).thenReturn(false);when(encoder.encode("StrongPass123")).thenReturn("hashed");when(users.save(any(AppUser.class))).thenAnswer(i->i.getArgument(0));var response=controller.signup(new AuthController.SignupRequest("Tenant User","Tenant@Example.com","StrongPass123",UserRole.TENANT));assertEquals(202,response.getStatusCode().value());assertEquals(AccountStatus.PENDING,((AppUser)capturedSavedUser()).getStatus());verify(jwt,never()).generate(anyString(),anyString());}
 private Object capturedSavedUser(){var captor=org.mockito.ArgumentCaptor.forClass(AppUser.class);verify(users).save(captor.capture());return captor.getValue();}
 @Test void pendingUserCannotLogin(){AppUser u=new AppUser("Tenant User","tenant@example.com","hashed",UserRole.TENANT);u.setStatus(AccountStatus.PENDING);when(users.findByEmailIgnoreCase("tenant@example.com")).thenReturn(Optional.of(u));when(encoder.matches("StrongPass123","hashed")).thenReturn(true);var response=controller.login(new AuthController.LoginRequest("tenant@example.com","StrongPass123"));assertEquals(403,response.getStatusCode().value());verify(jwt,never()).generate(anyString(),anyString());}
 @Test void publicSignupCannotCreateAdmin(){var response=controller.signup(new AuthController.SignupRequest("Admin User","admin@example.com","StrongPass123",UserRole.ADMIN));assertEquals(400,response.getStatusCode().value());verify(users,never()).save(any());}
 @Test void approvedUserCanLogin(){AppUser u=new AppUser("Tenant User","tenant@example.com","hashed",UserRole.TENANT);u.setStatus(AccountStatus.APPROVED);when(users.findByEmailIgnoreCase("tenant@example.com")).thenReturn(Optional.of(u));when(encoder.matches("StrongPass123","hashed")).thenReturn(true);when(jwt.generate("tenant@example.com","TENANT")).thenReturn("test-token");var response=controller.login(new AuthController.LoginRequest("tenant@example.com","StrongPass123"));assertEquals(200,response.getStatusCode().value());assertTrue(response.getBody() instanceof AuthController.AuthResponse);}
}
